std::queue<Triangulation::Face_handle> face_queue;
std::set<Triangulation::Face_handle> visited;

// Start from the infinite face, which is exterior (false)
Triangulation::Face_handle infinite = triangulation.infinite_face();
infinite->info() = false;
visited.insert(infinite);
face_queue.push(infinite);

while (!face_queue.empty()) {
    Triangulation::Face_handle current = face_queue.front();
    face_queue.pop();

    bool current_is_interior = current->info();

    for (int i = 0; i < 3; ++i) {
        Triangulation::Face_handle neighbor = current->neighbor(i);
        if (visited.find(neighbor) != visited.end())
            continue; // already processed

        // Determine if the edge between current and neighbor is a constraint
        Triangulation::Edge edge(current, i);
        bool is_constrained = triangulation.is_constrained(edge);

        // Flip interior flag when crossing a constrained edge
        neighbor->info() = current_is_interior ^ is_constrained;

        visited.insert(neighbor);
        face_queue.push(neighbor);
    }
}

